// ── ML pipeline components in code ─────────────────────────────

// 1. Data validation — fail loudly on bad data
function validateFeatures(record) {
  const errors = [];
  if (typeof record.age !== 'number' || record.age < 0 || record.age > 150) {
    errors.push(`Invalid age: ${record.age}`);
  }
  if (typeof record.purchaseAmount !== 'number' || record.purchaseAmount < 0) {
    errors.push(`Invalid purchaseAmount: ${record.purchaseAmount}`);
  }
  if (!['web', 'mobile', 'api'].includes(record.channel)) {
    errors.push(`Unknown channel: ${record.channel}`);
  }
  if (errors.length > 0) throw new Error(`Feature validation failed: ${errors.join('; ')}`);
  return true;
}

// 2. Feature computation — same logic for train and serve
function computeFeatures(rawRecord) {
  return {
    ageNormalised:     (rawRecord.age - 30) / 20,   // z-score approx
    logAmount:         Math.log1p(rawRecord.purchaseAmount),
    isWebChannel:      rawRecord.channel === 'web' ? 1 : 0,
    isMobileChannel:   rawRecord.channel === 'mobile' ? 1 : 0,
    hourOfDay:         new Date(rawRecord.timestamp).getHours()
  };
}

// 3. Model registry simulation (in production: MLflow, W&B, SageMaker)
const modelRegistry = new Map();

function registerModel(name, version, metrics, artifact) {
  const key = `${name}:${version}`;
  modelRegistry.set(key, {
    name, version, metrics, artifact,
    registeredAt: new Date().toISOString()
  });
  console.log(`Registered model ${key} — accuracy: ${metrics.accuracy}`);
  return key;
}

function getLatestModel(name) {
  const versions = [...modelRegistry.entries()]
    .filter(([k]) => k.startsWith(name))
    .sort(([,a], [,b]) => b.registeredAt.localeCompare(a.registeredAt));
  return versions[0]?.[1] ?? null;
}

// 4. Drift detection — Population Stability Index (PSI)
// PSI < 0.1: no drift. 0.1-0.25: moderate. > 0.25: significant drift.
function computePSI(expected, actual, bins = 10) {
  // Quantise both distributions into bins
  const allValues = [...expected, ...actual].sort((a, b) => a - b);
  const min = allValues[0], max = allValues[allValues.length - 1];
  const binWidth = (max - min) / bins;

  function toBinCounts(arr) {
    const counts = new Array(bins).fill(0);
    for (const v of arr) {
      const idx = Math.min(Math.floor((v - min) / binWidth), bins - 1);
      counts[idx]++;
    }
    return counts.map(c => Math.max(c / arr.length, 1e-9)); // proportions, avoid 0
  }

  const expProp = toBinCounts(expected);
  const actProp = toBinCounts(actual);

  const psi = expProp.reduce((sum, e, i) => {
    const a = actProp[i];
    return sum + (a - e) * Math.log(a / e);
  }, 0);

  return psi;
}

// Demo
const record = { age: 35, purchaseAmount: 149.99, channel: 'web', timestamp: Date.now() };
validateFeatures(record);
const features = computeFeatures(record);
console.log('Computed features:', features);

registerModel('fraud-detector', 'v1.2', { accuracy: 0.94, auc: 0.97 }, { path: '/models/fraud/v1.2' });
registerModel('fraud-detector', 'v1.3', { accuracy: 0.95, auc: 0.98 }, { path: '/models/fraud/v1.3' });
console.log('Latest model:', getLatestModel('fraud-detector').version); // v1.3

// Drift: compare training distribution vs recent serving distribution
const trainingAges = Array.from({length: 100}, () => 25 + Math.random() * 20); // 25-45
const servingAges  = Array.from({length: 100}, () => 40 + Math.random() * 25); // 40-65 (shifted)
const psi = computePSI(trainingAges, servingAges);
console.log(`PSI for age feature: ${psi.toFixed(3)} — ${psi > 0.25 ? 'DRIFT DETECTED' : psi > 0.1 ? 'moderate shift' : 'stable'}`);
// PSI will likely be > 0.25 — drift detected, trigger retraining

// ── MLOps vocabulary ────────────────────────────────────────────
//
// DATA PIPELINE
//   Orchestrated ETL from raw sources → clean features.
//   Tools: Apache Airflow, Prefect, dbt, Spark.
//   Key: idempotent, monitored, fails loudly on data quality issues.
//
// FEATURE STORE
//   Single source of truth for feature computation.
//   Training path (batch): historical feature values for labelled examples.
//   Serving path (online): real-time feature lookup for live predictions.
//   Eliminates training-serving skew.
//   Tools: Feast, Tecton, Vertex AI Feature Store, Databricks Feature Store.
//
// MODEL REGISTRY
//   Version-controlled storage of model artifacts + metadata.
//   Enables reproducibility, A/B testing, rollback.
//   Tools: MLflow, Weights & Biases, SageMaker Model Registry.
//
// SERVING
//   Model-as-a-service for real-time or batch inference.
//   Concerns: latency SLA, throughput, autoscaling, batching, hardware.
//   Tools: TorchServe, Triton, TF Serving, vLLM (for LLMs).
//
// MODEL DRIFT
//   Data drift:    input feature distribution changes.
//   Concept drift: feature → label relationship changes.
//   Detection:     PSI, KL divergence, output distribution monitoring,
//                  accuracy on labelled holdout windows.
//
// EVALUATION
//   Offline metrics: accuracy, AUC, RMSE (benchmark datasets).
//   Online A/B test: compare new model to champion on live traffic.
//   Slice analysis: performance by subgroup (age, region, device type).
//   Calibration:    predicted probabilities match empirical frequencies.
//
// SHADOW MODE
//   New model runs in parallel but predictions are NOT served to users.
//   Output is logged and compared to champion model offline.
//   Safe way to validate a new model before traffic cutover.
//
// CANARY DEPLOYMENT
//   Route a small % (1-5%) of traffic to new model.
//   Monitor metrics; roll back instantly if degradation detected.
//   Gradually increase traffic as confidence grows.
